function c($im,$hex,$a=0){$hex=ltrim($hex,'#');return imagecolorallocatealpha($im,hexdec(substr($hex,0,2)),hexdec(substr($hex,2,2)),hexdec(substr($hex,4,2)),$a);} imagefill($img,0,0,c($img,'050505'));
