function drawText($im,$text,$scale,$y,$color,$bg=null){$font=5;$fw=imagefontwidth($font);$fh=imagefontheight($font);$tw=$fw*strlen($text);$th=$fh;$tmp=imagecreatetruecolor($tw+4,$th+4);imagesavealpha($tmp,true);$clear=imagecolorallocatealpha($tmp,0,0,0,127);imagefill($tmp,0,0,$clear);imagestring($tmp,$font,2,2,$text,$color);$dstW=($tw+4)*$scale;$dstH=($th+4)*$scale;$x=(imagesx($im)-$dstW)/2;if($bg){imagefilledrectangle($im,$x-24,$y-20,$x+$dstW+24,$y+$dstH+20,$bg);}imagecopyresized($im,$tmp,(int)$x,$y,0,0,(int)$dstW,(int)$dstH,$tw+4,$th+4);imagedestroy($tmp);} $white=c($img,'f7f3e9');$yellow=c($img,'ffd24a');$orange=c($img,'ff4b1d');$dark=c($img,'100b08',10);
drawText($img,'JUST ONE KISS',6,90,$yellow);drawText($img,'YOU WANTED',10,265,$white);drawText($img,'THE BEST?',13,425,$white);drawText($img,'JULY 25 IS COMING.',6,645,$white);drawText($img,'Free show - July 25, 2026',3,800,$yellow,$dark);drawText($img,'Cycle Moore Legacy - Interlochen / US 31',3,860,$yellow,$dark);drawText($img,'Save July 25',6,1030,$white,$orange);drawText($img,'Independent theatrical rock tribute. No outside partnership claimed or implied.',2,1270,c($img,'bdb6a4'));drawText($img,'Loud sound, bright lights, fog, and flashing/strobe-style looks may be used.',2,1310,c($img,'bdb6a4'));
